CREATE TABLE IF NOT EXISTS kb_articles (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, category TEXT NOT NULL, title TEXT NOT NULL, summary TEXT, body TEXT NOT NULL, tags TEXT, link_url TEXT, author_name TEXT NOT NULL, author_batch TEXT, author_key TEXT NOT NULL, by_admin INTEGER DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', featured INTEGER DEFAULT 0, review_note TEXT, reviewed_by TEXT, reviewed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, ip TEXT, credits TEXT);
CREATE TABLE IF NOT EXISTS kb_stats (article_ref TEXT PRIMARY KEY, views INTEGER NOT NULL DEFAULT 0, helpful INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS kb_comments (id INTEGER PRIMARY KEY AUTOINCREMENT, article_ref TEXT NOT NULL, body TEXT NOT NULL, author_name TEXT NOT NULL, author_batch TEXT, author_key TEXT NOT NULL, by_admin INTEGER DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', review_note TEXT, reviewed_by TEXT, reviewed_at TEXT, created_at TEXT NOT NULL, ip TEXT);
